Looking at your current status and immediate blocker, let's define a focused Core MVP and break it down into actionable tasks.

## Core MVP Definition
**Goal**: Voice input → Real-time transcription → Display text
**Scope**: Single-user, browser-based, proving the core audio pipeline works

```
React PWA (WebRTC) → API Gateway (WebSocket) → STT Service (Whisper) → Redis Stream → React PWA (display)
```

## Immediate Tasks (Week 1)

### Task 1: WebRTC Audio Capture in React
```javascript
// components/AudioCapture.jsx
import { useState, useRef, useEffect } from 'react';

const AudioCapture = ({ onAudioData }) => {
  const [isRecording, setIsRecording] = useState(false);
  const mediaRecorder = useRef(null);
  const audioContext = useRef(null);
  const processor = useRef(null);

  const startRecording = async () => {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    audioContext.current = new AudioContext({ sampleRate: 16000 });
    const source = audioContext.current.createMediaStreamSource(stream);

    // Create ScriptProcessor for chunked audio
    processor.current = audioContext.current.createScriptProcessor(4096, 1, 1);
    processor.current.onaudioprocess = (e) => {
      const audioData = e.inputBuffer.getChannelData(0);
      const int16Array = new Int16Array(audioData.length);
      for (let i = 0; i < audioData.length; i++) {
        int16Array[i] = Math.max(-32768, Math.min(32767, audioData[i] * 32768));
      }
      onAudioData(int16Array.buffer);
    };

    source.connect(processor.current);
    processor.current.connect(audioContext.current.destination);
    setIsRecording(true);
  };

  const stopRecording = () => {
    processor.current?.disconnect();
    audioContext.current?.close();
    setIsRecording(false);
  };

  return (
    <button onClick={isRecording ? stopRecording : startRecording}>
      {isRecording ? 'Stop' : 'Start'} Recording
    </button>
  );
};
```

### Task 2: WebSocket Connection Manager
```javascript
// services/WebSocketService.js
class WebSocketService {
  constructor(url) {
    this.url = url;
    this.ws = null;
    this.sessionId = crypto.randomUUID();
  }

  connect() {
    return new Promise((resolve, reject) => {
      this.ws = new WebSocket(this.url);
      this.ws.binaryType = 'arraybuffer';

      this.ws.onopen = () => {
        console.log('WebSocket connected');
        this.sendInit();
        resolve();
      };

      this.ws.onerror = reject;
    });
  }

  sendInit() {
    this.ws.send(JSON.stringify({
      type: 'init',
      sessionId: this.sessionId,
      sampleRate: 16000
    }));
  }

  sendAudioChunk(audioData) {
    if (this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(audioData);
    }
  }
}
```

### Task 3: API Gateway WebSocket Handler
```javascript
// api-gateway/server.js
const WebSocket = require('ws');
const Redis = require('ioredis');

const wss = new WebSocket.Server({ port: 8080 });
const redis = new Redis();

wss.on('connection', (ws) => {
  let sessionId = null;

  ws.on('message', async (data) => {
    if (data instanceof Buffer) {
      // Audio chunk
      await redis.xadd('audio_stream', '*',
        'chunk', data.toString('base64'),
        'timestamp', Date.now(),
        'session_id', sessionId
      );
    } else {
      // Control message
      const msg = JSON.parse(data);
      if (msg.type === 'init') {
        sessionId = msg.sessionId;
        console.log(`Session initialized: ${sessionId}`);
      }
    }
  });
});
```

### Task 4: Basic STT Service
```python
# stt-service/main.py
import redis
import whisper
import numpy as np
import base64
import json

r = redis.Redis()
model = whisper.load_model("base")

def process_audio_stream():
    audio_buffer = []

    while True:
        # Read from Redis stream
        messages = r.xread({'audio_stream': '$'}, block=100)

        for stream_name, stream_messages in messages:
            for message_id, data in stream_messages:
                chunk_b64 = data[b'chunk'].decode()
                chunk = np.frombuffer(base64.b64decode(chunk_b64), dtype=np.int16)
                audio_buffer.append(chunk)

                # Process every 5 seconds of audio
                if len(audio_buffer) * 4096 / 16000 > 5:
                    audio = np.concatenate(audio_buffer).astype(np.float32) / 32768.0
                    result = model.transcribe(audio)

                    # Publish to text_stream
                    r.xadd('text_stream', '*',
                        'text', result['text'],
                        'confidence', 0.95,
                        'timestamp', data[b'timestamp'],
                        'session_id', data[b'session_id']
                    )

                    audio_buffer = []  # Reset buffer

if __name__ == "__main__":
    process_audio_stream()
```

